/* Deterministic mock controller. Never opens microphone, network, SIP, or provider session. */
export function createMockVoiceSession({onEvent=()=>{}}={}){let state="idle";const emit=(type,extra={})=>onEvent({type,state,at:"SYNTHETIC",...extra});return{get state(){return state},start(){if(state!=="idle")throw Error("session is not idle");state="connected";emit("session.started");return{recording:false,transcriptRetention:false}},sendSynthetic(text){if(state!=="connected")throw Error("session is not connected");emit("synthetic.input",{text});return{accepted:true,persistentRecord:false}},end(){if(state==="idle")return;state="ended";emit("session.ended")}}}
